  (1,1,'Welcome to 1st Semester 2025-2026!','This is the start of a new academic year. Please settle your membership fees on or before August 15, 2025.','all',10,'2025-08-01','2025-08-20',0,@now,@now),
  (2,1,'Acquaintance Night — Sept 5, 2025','Join us for the annual Acquaintance Night! Venue: University Covered Court. Contribution deadline: September 5.','students',10,'2025-08-25','2025-09-06',0,@now,@now),
  (3,1,'Organization Dev Fund Reminder','Kindly settle your Org Dev Fund contribution by October 1. Receipts will be issued per section treasurer.','students',10,'2025-09-20','2025-10-02',0,@now,@now),
  (4,1,'Class Trip — Reminders','Section treasurers will distribute trip details this week. Ensure trip fund is fully paid before October 15.','all',10,'2025-10-01','2025-10-16',0,@now,@now),
  (5,1,'2nd Semester Fees Are Now Open','2nd Semester fees are now open for payment. Please coordinate with your class treasurer.','all',10,'2026-01-05','2026-01-25',1,@now,@now),
  (6,1,'Foundation Day — Feb 14, 2026','Societech Foundation Day celebration on February 14! Contribution deadline is Feb 14.','all',10,'2026-01-20','2026-02-15',1,@now,@now),
  (7,1,'Graduation Celebration Fund','For graduating students: please settle the Graduation Celebration Fund on or before April 15, 2026.','students',10,'2026-03-01','2026-04-16',1,@now,@now),
  (8,1,'Fee Payment Reminder — 2nd Sem','Reminder: all 2nd semester fees are due by end of April. Coordinate with your section treasurer.','all',10,'2026-04-01','2026-05-01',1,@now,@now);

